import { act, fireEvent, render, screen, waitFor } from '@testing-library/react';
import { expect, it, vi } from 'vitest';
import { LikeButton } from './Solution';

function makeWriter() {
  const calls: boolean[] = [];
  const deferred: { resolve: () => void; reject: (e: unknown) => void } = {
    resolve: () => undefined,
    reject: () => undefined,
  };
  const onLike = (liked: boolean) => {
    calls.push(liked);
    return new Promise<void>((res, rej) => {
      deferred.resolve = res;
      deferred.reject = rej;
    });
  };
  return { calls, onLike, deferred };
}

it('未点赞时显示基准计数且无提示', () => {
  const w = makeWriter();
  render(<LikeButton baseCount={7} onLike={w.onLike} />);
  expect(screen.getByTestId('count').textContent).toBe('7');
  expect(screen.getByTestId('like').hasAttribute('disabled')).toBe(false);
  expect(screen.getByTestId('toast').textContent).toBe('');
});

it('单次点击立即显示乐观计数并禁用按钮', async () => {
  const noise: string[] = [];
  vi.spyOn(console, 'error').mockImplementation((...a: unknown[]) => noise.push(a.map(String).join(' ')));
  const w = makeWriter();
  render(<LikeButton baseCount={7} onLike={w.onLike} />);
  fireEvent.click(screen.getByTestId('like'));
  expect(screen.getByTestId('count').textContent).toBe('8');
  expect(screen.getByTestId('like').hasAttribute('disabled')).toBe(true);
  expect(screen.getByTestId('pending').textContent).toBe('true');
  await act(async () => { w.deferred.resolve(); await new Promise((r) => setTimeout(r, 0)); });
  expect(noise).toEqual([]);
});

it('重复点击在请求返回前不产生第二次写', async () => {
  const w = makeWriter();
  render(<LikeButton baseCount={0} onLike={w.onLike} />);
  fireEvent.click(screen.getByTestId('like'));
  fireEvent.click(screen.getByTestId('like'));
  fireEvent.click(screen.getByTestId('like'));
  expect(w.calls).toEqual([true]);
  expect(screen.getByTestId('count').textContent).toBe('1');
  await act(async () => { w.deferred.resolve(); await new Promise((r) => setTimeout(r, 0)); });
  expect(w.calls).toEqual([true]);
});

it('请求失败后乐观计数回弹并提示失败', async () => {
  const w = makeWriter();
  render(<LikeButton baseCount={7} onLike={w.onLike} />);
  fireEvent.click(screen.getByTestId('like'));
  expect(screen.getByTestId('count').textContent).toBe('8');
  await act(async () => { w.deferred.reject(new Error('422')); await new Promise((r) => setTimeout(r, 0)); });
  expect(screen.getByTestId('count').textContent).toBe('7');
  expect(screen.getByTestId('toast').textContent).toBe('save-failed');
  expect(screen.getByTestId('like').hasAttribute('disabled')).toBe(false);
  expect(w.calls).toEqual([true]);
});

it('成功后计数收敛且再次点击可撤销点赞', async () => {
  const w = makeWriter();
  render(<LikeButton baseCount={7} onLike={w.onLike} />);
  fireEvent.click(screen.getByTestId('like'));
  await act(async () => { w.deferred.resolve(); await new Promise((r) => setTimeout(r, 0)); });
  expect(screen.getByTestId('count').textContent).toBe('8');
  expect(screen.getByTestId('toast').textContent).toBe('');
  fireEvent.click(screen.getByTestId('like'));
  expect(screen.getByTestId('count').textContent).toBe('7');
  await act(async () => { w.deferred.resolve(); await new Promise((r) => setTimeout(r, 0)); });
  expect(w.calls).toEqual([true, false]);
  expect(screen.getByTestId('count').textContent).toBe('7');
});

