import { useOptimistic, useState, useTransition } from 'react';
import type { FormEvent } from 'react';

export interface LikeButtonProps {
  baseCount: number;
  onLike: (liked: boolean) => Promise<void>;
}

export function LikeButton({ baseCount, onLike }: LikeButtonProps) {
  const [liked, setLiked] = useState(false);
  const [toast, setToast] = useState('');
  const [optimisticLiked, toggle] = useOptimistic(liked, (state: boolean, next: boolean) => next);
  const [isPending, start] = useTransition();

  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const next = !optimisticLiked;
    start(async () => {
      // setOptimistic 必须在 Action/transition 内调用，否则会出现"闪一下又回弹"
      toggle(next);
      try {
        await onLike(next);
        setLiked(next);
        setToast('');
      } catch {
        // 不 rethrow：真值没更新，乐观态由 React 自动回弹，不需要手写 undo
        setToast('save-failed');
      }
    });
  }

  const count = baseCount + (optimisticLiked ? 1 : 0);

  return (
    <form onSubmit={submit}>
      <span data-testid="count">{count}</span>
      <span data-testid="pending">{String(isPending)}</span>
      <span data-testid="toast">{toast}</span>
      <button data-testid="like" type="submit" disabled={isPending}>
        like
      </button>
    </form>
  );
}

