import { useState } from 'react';

export function LikeButton({ baseCount, onLike }: { baseCount: number; onLike: (liked: boolean) => Promise<void> }) {
  const [liked, setLiked] = useState(false);
  const [toast, setToast] = useState('');
  async function handleClick() {
    const next = !liked;
    setLiked(next);
    try {
      await onLike(next);
      setToast('');
    } catch {
      setLiked(!next);
      setToast('save-failed');
    }
  }
  return (
    <div>
      <span data-testid="count">{baseCount + (liked ? 1 : 0)}</span>
      <span data-testid="pending">{String(false)}</span>
      <span data-testid="toast">{toast}</span>
      <button data-testid="like" onClick={handleClick}>like</button>
    </div>
  );
}
